// بديل لـ node-fetch يحوّل روابط ديسكورد و Groq إلى سيرفر الاختبار المحلي
const base = process.env.MOCK_BASE;
const rewrite = (u) => String(u).replace("https://discord.com", base).replace("https://api.groq.com", base);
const f = (url, opts) => fetch(rewrite(url), opts);
module.exports = f;
module.exports.default = f;
